package com.fulllock.app;
import android.app.*;import android.content.*;import android.os.*;import android.service.notification.*;import java.io.PrintWriter;import java.lang.reflect.Field;
/** Not in normal builds. Invoked only by the shell/system DUMP path of a local test APK. */
public final class DeviceNotificationChecks {
 private record Observed(ScreenCardParser.Card card,String reference,long at){}
 private static volatile Observed observed;
 public static void capture(ScreenCardParser.Card card,String reference,long at){observed=new Observed(card,reference,at);}
 private static java.util.Map<String,Object> backup;
 private static void apply(android.content.SharedPreferences.Editor edit,String key,Object value){if(value==null)edit.remove(key);else if(value instanceof Boolean b)edit.putBoolean(key,b);else if(value instanceof Integer i)edit.putInt(key,i);else if(value instanceof String text)edit.putString(key,text);}

 public static void run(Context c,String[] args,PrintWriter out)throws Exception{
  if(!BuildConfig.DEVICE_NOTIFICATION_CHECKS)return;Field field=JobListener.class.getDeclaredField("instance");field.setAccessible(true);JobListener listener=(JobListener)field.get(null);out.println("listener="+JobListener.connected+" instance="+(listener!=null)+" auto="+Store.prefs(c).getBoolean("enabled",false)+" root="+RootMode.enabled(c));
  java.util.List<String> options=java.util.Arrays.asList(args);
  if(options.contains("device-notification-open-first-card")){new Handler(Looper.getMainLooper()).post(()->{Store.prefs(c).edit().putBoolean("enabled",false).apply();ScreenActions.request(c,ScreenActions.firstVisible());});out.println("queued validated native card open only");return;}
  if(options.contains("device-notification-arm-current")){Observed current=observed;if(current==null||SystemClock.elapsedRealtime()-current.at()>500){out.println("No fresh detail observation");return;}int seconds=3;for(String arg:args)if(arg.startsWith("delay="))seconds=Math.max(0,Math.min(20,Integer.parseInt(arg.substring(6))));final int delay=seconds;new Handler(Looper.getMainLooper()).post(()->{NotificationOpener.cancel(c);Store.prefs(c).edit().putBoolean("enabled",true).putBoolean("rootDistanceOn",true).putString("rootDistanceMin","0").putString("rootDistanceMax","0").putBoolean("rootDetailReturnOn",true).putInt("rootDetailReturnSeconds",delay).apply();DetailActions.arm(current.card().job(),current.reference());});out.println("controlled notification-origin guard armed for current real detail; no accept action");return;}
  if(options.contains("device-notification-adjust-mismatch")){int seconds=3;for(String arg:args)if(arg.startsWith("delay="))seconds=Math.max(0,Math.min(20,Integer.parseInt(arg.substring(6))));final int delay=seconds;new Handler(Looper.getMainLooper()).post(()->Store.prefs(c).edit().putBoolean("rootDistanceOn",true).putString("rootDistanceMin","0").putString("rootDistanceMax","0").putBoolean("rootDetailReturnOn",true).putInt("rootDetailReturnSeconds",delay).apply());out.println("rejection threshold adjusted on current notification-opened detail");return;}
  if(options.contains("device-notification-restore")){new Handler(Looper.getMainLooper()).post(()->{NotificationOpener.cancel(c);if(backup!=null){var edit=Store.prefs(c).edit();for(var value:backup.entrySet())apply(edit,value.getKey(),value.getValue());edit.apply();backup=null;}});out.println("restore queued");return;}
  if(options.contains("device-notification-prepare-match")||options.contains("device-notification-prepare-mismatch")){
   boolean mismatch=options.contains("device-notification-prepare-mismatch");int seconds=3;for(String arg:args)if(arg.startsWith("delay="))seconds=Math.max(0,Math.min(20,Integer.parseInt(arg.substring(6))));final int delay=seconds;
   new Handler(Looper.getMainLooper()).post(()->{var prefs=Store.prefs(c);java.util.Map<String,Object> values=new java.util.LinkedHashMap<>();values.put("enabled",false);values.put("price",false);values.put("originOn",false);values.put("destOn",false);values.put("excludeOriginOn",false);values.put("excludeDestOn",false);values.put("type",0);values.put("serviceMask",1);values.put("rootPayment","");values.put("rootPricing","");values.put("rootServicesOn",false);values.put("rootRateOn",false);values.put("rootPickupOn",false);values.put("rootPriorityOn",false);values.put("rootDistanceOn",mismatch);values.put("rootDistanceMin","0");values.put("rootDistanceMax","0");values.put("rootDetailReturnOn",true);values.put("rootDetailReturnSeconds",delay);values.put("cardShowPickup",true);if(backup==null){backup=new java.util.LinkedHashMap<>();var all=prefs.getAll();for(String key:values.keySet())backup.put(key,all.get(key));}var edit=prefs.edit();for(var value:values.entrySet())apply(edit,value.getKey(),value.getValue());edit.apply();});out.println("bounded test configuration queued");return;
  }
  Field guardField=NotificationOpener.class.getDeclaredField("guard");guardField.setAccessible(true);NotificationOpenGuard guard=(NotificationOpenGuard)guardField.get(null);out.println("opening="+guard.state());Field rootField=NotificationOpener.class.getDeclaredField("rootRequired");rootField.setAccessible(true);out.println("rootSender="+rootField.getBoolean(null));try{var history=new org.json.JSONArray(Store.prefs(c).getString("history","[]"));for(int i=0;i<history.length();i++){var item=history.getJSONObject(i);if(!item.optString("openAttempt").isEmpty()){out.println("lastOpening="+item.optString("result")+" confirmed="+item.optBoolean("worked"));break;}}}catch(Exception ignored){}
  if(listener==null||!JobListener.connected)return;StatusBarNotification selected=null;JobParser.Job selectedJob=null;int offers=0,actions=0;java.util.List<StatusBarNotification> eligible=new java.util.ArrayList<>();java.util.Map<String,JobParser.Job> parsed=new java.util.HashMap<>();java.util.Set<PendingIntent> unique=new java.util.HashSet<>();
  for(StatusBarNotification item:listener.getActiveNotifications())if(JobListener.DRIVER.equals(item.getPackageName())){Notification n=item.getNotification();String title=String.valueOf(n.extras.getCharSequence(Notification.EXTRA_TITLE,""));String regular=String.valueOf(n.extras.getCharSequence(Notification.EXTRA_TEXT,""));CharSequence big=n.extras.getCharSequence(Notification.EXTRA_BIG_TEXT);String text=big==null||big.toString().isBlank()?regular:big.toString();JobParser.Job job=JobParser.notificationJob(title,text,(n.flags&Notification.FLAG_ONGOING_EVENT)!=0,(n.flags&Notification.FLAG_GROUP_SUMMARY)!=0);if(job==null)continue;offers++;if(n.contentIntent!=null){actions++;eligible.add(item);parsed.put(item.getKey(),job);unique.add(n.contentIntent);if(selected==null||item.getPostTime()>selected.getPostTime()){selected=item;selectedJob=job;}}}
  eligible.sort(java.util.Comparator.comparingLong(StatusBarNotification::getPostTime).reversed());int index=0;for(String arg:args)if(arg.startsWith("index="))index=Math.max(0,Math.min(4,Integer.parseInt(arg.substring(6))));if(index<eligible.size()){selected=eligible.get(index);selectedJob=parsed.get(selected.getKey());}out.println("jobOffers="+offers+" openableOffers="+actions+" distinctActions="+unique.size()+" selectedAgeSeconds="+(selected==null?-1:(System.currentTimeMillis()-selected.getPostTime())/1000));
  if(java.util.Arrays.asList(args).contains("device-notification-open-latest")){if(selected==null){out.println("No eligible test action");return;}StatusBarNotification chosen=selected;JobParser.Job job=selectedJob;Notification n=chosen.getNotification();String title=String.valueOf(n.extras.getCharSequence(Notification.EXTRA_TITLE,""));String regular=String.valueOf(n.extras.getCharSequence(Notification.EXTRA_TEXT,""));CharSequence big=n.extras.getCharSequence(Notification.EXTRA_BIG_TEXT);String text=big==null||big.toString().isBlank()?regular:big.toString();String uuid="";for(String key:new String[]{"order_uuid","uuid"}){Object value=n.extras.get(key);if(value instanceof String id&&!id.isBlank()&&id.length()<=128){uuid=id;break;}}String id=uuid;new Handler(Looper.getMainLooper()).post(()->{Store.prefs(c).edit().putBoolean("enabled",true).apply();NotificationOpener.open(c,n.contentIntent,job,chosen.getKey(),chosen.getPostTime(),title,text,id);});out.println("queued fixed Driver PendingIntent; no accept gesture");}
 }
}
